WHERE status = 'ON_SHELF'

    AND (LOWER(title) LIKE #{keywordPattern} ESCAPE '!' OR LOWER(author) LIKE #{keywordPattern} ESCAPE '!')


    AND format = #{format}


    AND category = #{category}

mapper.select:
SELECT 
FROM book


ORDER BY ${sort.orderBy}
LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE book
SET available_copies = available_copies - 1,
    updated_at       = #{now}
WHERE id = #{id}
  AND status = 'ON_SHELF'
  AND available_copies > 0

UPDATE book
SET available_copies = available_copies + 1,
    updated_at       = #{now}
WHERE id = #{id}
  AND available_copies < total_copies
